package com.minhnb.finvera_be.alert.service;import static com.minhnb.finvera_be.alert.dto.AlertDtos.*;import com.minhnb.finvera_be.alert.entity.AlertNotificationEntity;import com.minhnb.finvera_be.alert.repository.AlertNotificationRepository;import java.time.*;import java.util.UUID;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service public class NotificationService{private final AlertNotificationRepository repo;private final OwnerScopedAlertAccess access;private final Clock clock;public NotificationService(AlertNotificationRepository r,OwnerScopedAlertAccess a,Clock c){repo=r;access=a;clock=c;}@Transactional(readOnly=true)public PageResponse<NotificationResponse> list(boolean unread,int limit,int offset){UUID o=access.getAuthenticatedOwnerId();var page=unread?repo.findByOwnerIdAndReadAtIsNullOrderByDeliveredAtDescIdDesc(o,OffsetPageRequest.of(offset,limit)):repo.findByOwnerIdOrderByDeliveredAtDescIdDesc(o,OffsetPageRequest.of(offset,limit));return new PageResponse<>(page.getContent().stream().map(NotificationService::map).toList(),page.getTotalElements(),limit,offset);}@Transactional(readOnly=true)public NotificationResponse get(UUID id){return map(owned(id));}@Transactional(readOnly=true)public long unread(){return repo.countByOwnerIdAndReadAtIsNull(access.getAuthenticatedOwnerId());}@Transactional public NotificationResponse read(UUID id){var n=owned(id);n.markRead(clock.instant());return map(n);}@Transactional public ReadAllResponse readAll(){Instant now=clock.instant();return new ReadAllResponse(repo.markAllRead(access.getAuthenticatedOwnerId(),now),now);}private AlertNotificationEntity owned(UUID id){return repo.findByIdAndOwnerId(id,access.getAuthenticatedOwnerId()).orElseThrow(AlertExceptions.NotificationNotFoundException::new);}static NotificationResponse map(AlertNotificationEntity n){return new NotificationResponse(n.getId(),n.getAlertId(),n.getTitle(),n.getMessage(),n.getConditionSnapshot(),n.getEvidence(),n.getTriggeredAt(),n.getDeliveredAt(),n.getReadAt());}}
